using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
public static partial class HedgeDetailUpdater {
static void MedianAudit(){var sc=SceneManager.GetActiveScene();var fs=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Where(f=>f.name=="polySurface880").ToArray();string log="scene="+sc.path+" targetCount="+fs.Length+" selection="+Selection.activeGameObject?.name+"\n";foreach(var f in fs){var r=f.GetComponent<Renderer>();log+="TARGET "+f.name+" position="+f.transform.position+" rotation="+f.transform.eulerAngles+" scale="+f.transform.lossyScale+" bounds="+r.bounds+" mesh="+AssetDatabase.GetAssetPath(f.sharedMesh)+"/"+f.sharedMesh.name+" materials="+string.Join(",",r.sharedMaterials.Select(m=>AssetDatabase.GetAssetPath(m)))+"\n";foreach(var q in sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).Where(q=>Vector3.Distance(q.bounds.center,r.bounds.center)<18).OrderBy(q=>Vector3.Distance(q.bounds.center,r.bounds.center)).Take(35))log+=q.name+" pos="+q.transform.position+" bounds="+q.bounds+" mesh="+(q.GetComponent<MeshFilter>()?q.GetComponent<MeshFilter>().sharedMesh?.name:"")+"\n";}if(fs.Length>0){var rb=fs[0].GetComponent<Renderer>().bounds;foreach(var r in sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).Where(r=>Vector3.Distance(rb.ClosestPoint(r.bounds.center),r.bounds.center)<5&&(r.name.ToLower().Contains("green")||r.name.ToLower().Contains("fence")||r.name.ToLower().Contains("railing")||r.name.ToLower().Contains("palm"))))log+="NEAR "+r.name+" position="+r.transform.position+" rotation="+r.transform.eulerAngles+" scale="+r.transform.lossyScale+" bounds="+r.bounds+" mesh="+(r.GetComponent<MeshFilter>()?AssetDatabase.GetAssetPath(r.GetComponent<MeshFilter>().sharedMesh):"")+" materials="+string.Join(",",r.sharedMaterials.Where(m=>m).Select(m=>AssetDatabase.GetAssetPath(m)))+"\\n";}File.WriteAllText("FinalEnvironmentRoadReview/Median880Audit.txt",log);}
}

